class ItemRow extends DataClass implements Insertable<ItemRow> {
  final int id;
  final int sourceId;

  /// Path relative to the source root, `/`-separated, no leading slash.
  final String relPath;

  /// Parent folder of [relPath] (`''` for the root) for folder mode (LIB-004).
  final String parentPath;
  final String name;
  final String ext;
  final ItemKind kind;
  final int size;
  final DateTime mtime;

  /// xxh3-64 of the first and last MiB plus size, hex (move detection).
  final String? contentHash;
  final DateTime addedAt;
  final DateTime scannedAt;

  /// File vanished on the last scan; kept so a move can be re-linked.
  final bool missing;
  final bool hidden;
  final bool vault;

  /// Display title (metadata title, scraped title or cleaned file name).
  final String title;
  final String sortTitle;
  final int? durationMs;
  final int? width;
  final int? height;
  final String? videoCodec;
  final String? audioCodec;

  /// none / hdr10 / hdr10plus / hlg / dolbyVision.
  final String? hdrType;

  /// e.g. `stereo`, `5.1`, `7.1.4`.
  final String? audioLayout;
  final int subtitleTracks;
  final int audioTracks;
  final int playCount;
  final DateTime? lastPlayedAt;

  /// Probe finished (metadata facts are valid).
  final bool probed;
  final DateTime? takenAt;
  const ItemRow({
    required this.id,
    required this.sourceId,
    required this.relPath,
    required this.parentPath,
    required this.name,
    required this.ext,
    required this.kind,
    required this.size,
    required this.mtime,
    this.contentHash,
    required this.addedAt,
    required this.scannedAt,
    required this.missing,
    required this.hidden,
    required this.vault,
    required this.title,
    required this.sortTitle,
    this.durationMs,
    this.width,
    this.height,
    this.videoCodec,
    this.audioCodec,
    this.hdrType,
    this.audioLayout,
    required this.subtitleTracks,
    required this.audioTracks,
    required this.playCount,
    this.lastPlayedAt,
    required this.probed,
    this.takenAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['source_id'] = Variable<int>(sourceId);
    map['rel_path'] = Variable<String>(relPath);
    map['parent_path'] = Variable<String>(parentPath);
    map['name'] = Variable<String>(name);
    map['ext'] = Variable<String>(ext);
    {
      map['kind'] = Variable<String>($ItemsTable.$converterkind.toSql(kind));
    }
    map['size'] = Variable<int>(size);
    map['mtime'] = Variable<DateTime>(mtime);
    if (!nullToAbsent || contentHash != null) {
      map['content_hash'] = Variable<String>(contentHash);
    }
    map['added_at'] = Variable<DateTime>(addedAt);
    map['scanned_at'] = Variable<DateTime>(scannedAt);
    map['missing'] = Variable<bool>(missing);
    map['hidden'] = Variable<bool>(hidden);
    map['vault'] = Variable<bool>(vault);
    map['title'] = Variable<String>(title);
    map['sort_title'] = Variable<String>(sortTitle);
    if (!nullToAbsent || durationMs != null) {
      map['duration_ms'] = Variable<int>(durationMs);
    }
    if (!nullToAbsent || width != null) {
      map['width'] = Variable<int>(width);
    }
    if (!nullToAbsent || height != null) {
      map['height'] = Variable<int>(height);
    }
    if (!nullToAbsent || videoCodec != null) {
      map['video_codec'] = Variable<String>(videoCodec);
    }
    if (!nullToAbsent || audioCodec != null) {
      map['audio_codec'] = Variable<String>(audioCodec);
    }
    if (!nullToAbsent || hdrType != null) {
      map['hdr_type'] = Variable<String>(hdrType);
    }
    if (!nullToAbsent || audioLayout != null) {
      map['audio_layout'] = Variable<String>(audioLayout);
    }
    map['subtitle_tracks'] = Variable<int>(subtitleTracks);
    map['audio_tracks'] = Variable<int>(audioTracks);
    map['play_count'] = Variable<int>(playCount);
    if (!nullToAbsent || lastPlayedAt != null) {
      map['last_played_at'] = Variable<DateTime>(lastPlayedAt);
    }
    map['probed'] = Variable<bool>(probed);
    if (!nullToAbsent || takenAt != null) {
      map['taken_at'] = Variable<DateTime>(takenAt);
    }
    return map;
  }

  ItemsCompanion toCompanion(bool nullToAbsent) {
    return ItemsCompanion(
      id: Value(id),
      sourceId: Value(sourceId),
      relPath: Value(relPath),
